import{_ as i,o as l,c as t,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph CI and Developer Tooling- Past, Present, and Futur","description":"","frontmatter":{"title":"Ceph CI and Developer Tooling- Past, Present, and Futur","date":"2026-04-20T00:00:00.000Z","updated":"2026-04-21T00:00:00.000Z","tags":["Ceph CI","持续集成","开发者工具","测试基础设施","Teuthology"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_CI_and_Developer_Tooling_-_Past_Present_and_Futur.md","filePath":"posts/2026/Ceph_CI_and_Developer_Tooling_-_Past_Present_and_Futur.md","lastUpdated":1780459816000}'),o={name:"posts/2026/Ceph_CI_and_Developer_Tooling_-_Past_Present_and_Futur.md"};function a(r,e,s,h,u,p){return l(),t("div",null,[...e[0]||(e[0]=[n('<h2 id="演讲者介绍" tabindex="-1">演讲者介绍 <a class="header-anchor" href="#演讲者介绍" aria-label="Permalink to &quot;演讲者介绍&quot;">​</a></h2><p>本次演讲由 David Galloway 主讲。他于 2010 年加入 Red Hat 内部帮助台，2012 年转入工程部门。随着 InkTank 被 Red Hat 收购，他成为 Ceph 实验室的专职资源，负责机架安装、布线及初期硬件投资的落地工作，并参与了实验室从 Irvine 迁移至 Morisville 的全过程。</p><p>团队成员（按入职时间排序）：</p><ul><li><strong>Dan Mick</strong>：随 InkTank 收购一同加入</li><li><strong>Adam Kreitman</strong>：2019 年加入，带来 Ansible、Jenkins 及云计算经验</li><li><strong>Evelyn</strong>：项目经理，2024 年加入</li><li><strong>Fernando</strong>：安全方向，2024 年加入</li><li><strong>Jitendra</strong>：最新成员，近期贡献突出</li></ul><h2 id="ceph-实验室的历史沿革" tabindex="-1">Ceph 实验室的历史沿革 <a class="header-anchor" href="#ceph-实验室的历史沿革" aria-label="Permalink to &quot;Ceph 实验室的历史沿革&quot;">​</a></h2><p><strong>2014 年</strong>：InkTank 被 Red Hat 收购，实验室主体位于加利福尼亚州 Irvine 的托管数据中心。</p><p><strong>2015 年初</strong>：Red Hat 完成初期硬件投资，David 完成机架安装与布线，并将 Irvine 的大部分设备迁移至北卡罗来纳州 Morrisville 的 Red Hat 托管空间。收购后实验室分为两个独立部分：</p><ul><li><strong>上游开发与测试实验室</strong>：位于 Red Hat 社区机柜，对社区成员开放</li><li><strong>下游实验室（Octo Lab）</strong>：主要面向 QE，位于 Red Hat 防火墙之后</li></ul><p><strong>2022 年</strong>：Ceph 项目完全并入 IBM，实验室再次迁移：</p><ul><li>下游 Octo Lab 迁至亚利桑那州 Tucson</li><li>上游实验室迁至纽约州 Poughkeepsie（约四分之三的设备仍处于网络接入待完成状态）</li></ul><h2 id="为什么-ceph-ci-如此复杂" tabindex="-1">为什么 Ceph CI 如此复杂 <a class="header-anchor" href="#为什么-ceph-ci-如此复杂" aria-label="Permalink to &quot;为什么 Ceph CI 如此复杂&quot;">​</a></h2><p><strong>多发行版支持</strong>：目前需在以下平台上构建和支持 Ceph：</p><ul><li>CentOS 8、9，Rocky 10</li><li>Ubuntu 20、22、24</li><li>若干 Debian 版本</li><li>Windows 驱动</li></ul><p>近期重大改进：已实现在容器内构建 Ceph，Ubuntu 宿主机可构建 RPM，反之亦然。</p><p><strong>多架构支持</strong>：上游支持 x86 和 arm64，下游还支持 Power 和 s390x。</p><p><strong>硬件维护挑战</strong>：各硬件厂商提供工程样机用于测试，维护这些样机极为繁琐。演讲者展示了为早期 arm 原型手工制作串口转接头的电路图，以及用于固件刷写的工具。</p><p><strong>规模化集成测试</strong>：每天运行约 2,000 至 3,000 个集成测试任务，每个任务会锁定 1 至 4 台裸金属服务器，完整流程包括：安装操作系统、运行配置管理、安装 Ceph、执行集成测试（部分测试会对磁盘和网络设备进行压力测试）。</p><p><strong>自定义 Python 微服务依赖</strong>：团队重度依赖若干自研 Python 微服务，调试难度较高。</p><h2 id="ci-历史回顾" tabindex="-1">CI 历史回顾 <a class="header-anchor" href="#ci-历史回顾" aria-label="Permalink to &quot;CI 历史回顾&quot;">​</a></h2><h3 id="gitbuilders-时代" tabindex="-1">GitBuilders 时代 <a class="header-anchor" href="#gitbuilders-时代" aria-label="Permalink to &quot;GitBuilders 时代&quot;">​</a></h3><p>GitBuilders 是早期的构建系统，每台裸金属或虚拟机专门负责构建特定发行版和架构组合（例如：CentOS 6 x86 TCMalloc）。每次只能构建一个版本，构建耗时约 4 小时，每天最多只能构建约 6 个分支，开发者常需要等待数天才能获得二进制包。构建产物也由同一台 GitBuilder 提供服务，一旦宕机影响极大。</p><h3 id="vps-测试阶段" tabindex="-1">VPS 测试阶段 <a class="header-anchor" href="#vps-测试阶段" aria-label="Permalink to &quot;VPS 测试阶段&quot;">​</a></h3><p>在拥有大量裸金属测试节点之前，集成测试主要在虚拟机（VPS）上运行：</p><ul><li>约 100 台2U 服务器，每台配备单四核处理器、32GB 内存、8 块 1TB 机械硬盘</li><li>每台 VPS 宿主机运行 8 个虚拟机（单 vCPU、4GB 内存、1块硬盘）</li><li>使用 cloud-init 和自研工具 <strong>downburst</strong>（基于 libvirt）快速部署实例</li><li>曾短暂使用 OVH 公有云运行 Teuthology 任务，但因稳定性问题放弃</li></ul><h3 id="监控与资产管理" tabindex="-1">监控与资产管理 <a class="header-anchor" href="#监控与资产管理" aria-label="Permalink to &quot;监控与资产管理&quot;">​</a></h3><ul><li>直到 InkTank 并入 Red Hat 后才开始使用数据中心资产管理工具</li><li>2015 年引入 Nagios 实现集中监控告警，现已迁移至 Grafana</li><li>曾有一个手动维护的状态门户，Nagios 下线后随之废弃</li></ul><h3 id="jenkins-演进" tabindex="-1">Jenkins 演进 <a class="header-anchor" href="#jenkins-演进" aria-label="Permalink to &quot;Jenkins 演进&quot;">​</a></h3><p>Ceph 项目在 Jenkins 方面长期落后于业界：</p><ul><li>2015 年才开始运行 make check</li><li>直到去年才开始使用 Jenkins Pipeline 功能</li><li>Pipeline 之前，同一分支的 8 种发行版/架构组合需要分别构建同一份源码 tarball</li></ul><h2 id="当前-ci-架构-present" tabindex="-1">当前 CI 架构（Present） <a class="header-anchor" href="#当前-ci-架构-present" aria-label="Permalink to &quot;当前 CI 架构（Present）&quot;">​</a></h2><h3 id="完整流程概述" tabindex="-1">完整流程概述 <a class="header-anchor" href="#完整流程概述" aria-label="Permalink to &quot;完整流程概述&quot;">​</a></h3><ol><li><strong>需求跟踪</strong>：开发者从 tracker.ceph.com（Redmine）获取任务</li><li><strong>代码开发</strong>：从 GitHub fork/clone Ceph 仓库，可使用 <strong>VStart cluster</strong> 在本地部署轻量级单节点 Ceph 集群进行验证</li><li><strong>触发构建</strong>：推送分支至 Ceph CI Git 仓库，GitHub webhook 触发 Jenkins 构建任务</li><li><strong>Jenkins 构建</strong>： <ul><li>所有 Jenkins 任务以YAML 定义，通过 OpenStack 的 Jenkins Job Builder 工具推送至 Jenkins</li><li>构建在 Poughkeepsie 实验室的裸金属 Jenkins builder 上运行</li><li>每台 builder 使用 4-5 个 Ansible role 初始化，当前每台只有 1 个 executor</li></ul></li><li><strong>源码 tarball 构建</strong>：Ceph dev pipeline 启动 source dist 任务，构建源码 tarball 并上传至 Jenkins，随后为每种发行版和架构创建 builder 容器</li><li><strong>包存储与分发</strong>： <ul><li>构建完成的包推送至 <strong>Chakra</strong>（自研 Python 微服务，提供 API、二进制存储和 repo 托管，保存 14 天）</li><li>Chakra 通知 <strong>Shaman</strong>（另一自研 Python 微服务，含数据库、API 和 Web UI）repo 已就绪</li></ul></li><li><strong>容器镜像构建</strong>：基于 Rocky Linux 10（本周刚切换为默认基础镜像），安装运行时依赖和 Ceph 包，发布开发容器镜像至 quay.ceph.io</li><li><strong>集成测试（Teuthology）</strong>： <ul><li>Teuthology 通过 Padles（API +数据库）管理测试节点和任务结果，Pulpito 提供 Web 展示</li><li>dispatcher 守护进程通过 beanstalkd 调度任务</li><li>测试节点通过 <strong>FOG</strong>（Fully Open Ghost）项目进行系统重装：IPMI 上电 → DHCP → PXE boot → FOG OS →流式写入 gold OS镜像（预装 Ceph 测试依赖）→ 重启 → Ansible 配置（zap NVMe 用于 OSD 等）→ 安装 Ceph → 运行 QA 测试</li><li>每个任务结束后，内核日志、syslog、core dump 及任务日志写入 <strong>CephFS</strong> 挂载点，存储于长期运行集群（LRC，同时作为 dogfood 集群验证预发布版本）</li></ul></li><li><strong>PR 检查</strong>：每个 PR 触发 17 项检查： <ul><li>Jenkins（9 项）：make check、API 测试、Windows 测试等，每项耗时 1-2 小时</li><li>GitHub Actions（7 项）：PR 标签分配、rebase 检查等</li><li>Read the Docs（1 项）：文档构建与语法检查</li></ul></li></ol><h3 id="正式发布流程" tabindex="-1">正式发布流程 <a class="header-anchor" href="#正式发布流程" aria-label="Permalink to &quot;正式发布流程&quot;">​</a></h3><ol><li>变更合并至主分支后，视情况向各 release 分支（如 Tentacle）提交 backport PR</li><li>QE 流程：批量合并 PR 至独立 CephCI 分支，构建并跑完所有 Teuthology 测试套件</li><li>组负责人审批测试结果后，手动触发 <strong>Ceph release pipeline</strong> Jenkins 任务</li><li>构建产物推送至独立 Chakra 实例（仅存储待签名的预发布包）</li><li>手动 rsync 至实验室 VM <strong>Signer</strong>（通过 Nitrokey USB 设备安全存储 GPG 签名密钥）</li><li>签名后推送至 download.ceph.com 的密码保护暂存目录</li><li>手动触发容器构建，x86 和 arm64 容器合并后推送至 quay.io</li><li>发布公告与 Release Notes 发布</li></ol><h2 id="当前痛点" tabindex="-1">当前痛点 <a class="header-anchor" href="#当前痛点" aria-label="Permalink to &quot;当前痛点&quot;">​</a></h2><ul><li><strong>重复构建</strong>：每个 PR 的二进制包被构建 3 次（make check、API 测试、Windows 任务各一次），正在推进容器化以实现一次构建多处复用</li><li><strong>跨发行版测试差异</strong>：单元测试在 Jamy 上通过但在 Noble 上失败的情况时有发生</li><li><strong>构建状态可见性差</strong>：Shaman 只有在构建实际开始后才感知到任务，Jenkins 队列积压时开发者可能重复 force push 反而延误自己的构建</li><li><strong>基础设施故障影响 CI</strong>：近期发生测试节点磁盘故障导致数十个 Teuthology 任务失败，此类问题本应在影响 CI 前被提前发现</li><li><strong>Shaman/Chakra 技术债</strong>：十年前因缺乏跨发行版工具而自研，现已有 <strong>Pulp</strong> 等现代开源替代方案，团队正在评估迁移</li><li><strong>Jenkins 任务效率低下</strong>：部分任务仅需运行几秒钟的脚本，却要花费大量时间从 GitHub clone 整个 Ceph 仓库，应迁移至 GitHub Actions；团队在 GitHub Actions 方面经验不足，正在学习中</li><li><strong>单 executor 资源浪费</strong>：96 核 builder 运行单线程任务时，95 个核心处于闲置状态</li></ul><h2 id="未来规划-future" tabindex="-1">未来规划（Future） <a class="header-anchor" href="#未来规划-future" aria-label="Permalink to &quot;未来规划（Future）&quot;">​</a></h2><p>当前年度实验室优先事项：</p><p><strong>开发者与管理层友好的指标和 Dashboard</strong>：</p><ul><li>团队成员 Evelyn 已发出调查问卷，收集开发者最关心的指标</li><li>已上线示例 Dashboard，展示 Jenkins 队列中的等待任务数、PR 任务等待启动时长等关键指标</li><li>随着 Red Hat 设备迁入 IBM 并完成布线，队列积压情况已明显改善（此前高峰期等待时间达 4-5 小时）</li></ul><p><strong>持续推进容器化</strong>：将更多构建和测试任务迁移至容器，提升资源利用率和跨平台一致性。</p><p><strong>GitHub Actions 能力建设</strong>：将适合的轻量级任务（如 commit 签名检查）迁移至 GitHub Actions，减少对 Jenkins builder 的不必要占用。</p>',42)])])}const c=i(o,[["render",a]]);export{g as __pageData,c as default};
